/**
 * Fetches all pages from a cursor-based paginated API, retrying each page
 * request with exponential backoff on failure.
 *
 * @param {Function} fetchPage - async (cursor?) => { items: any[], nextCursor?: string }
 * @param {Object}   [options]
 * @param {number}   [options.maxRetries=5]     - max retries per page request
 * @param {number}   [options.baseDelay=1000]   - initial delay in ms
 * @param {number}   [options.maxDelay=30000]   - cap for backoff delay in ms
 * @param {number}   [options.backoffFactor=2]  - multiplier for each retry
 * @param {Function} [options.onRetry]          - (error, attempt, delay) callback
 * @param {AbortSignal} [options.signal]        - optional abort signal
 * @returns {Promise<{items: any[], pages: number}>}
 */
async function retry_with_backoff(fetchPage, options = {}) {
  const {
    maxRetries = 5,
    baseDelay = 1000,
    maxDelay = 30000,
    backoffFactor = 2,
    onRetry = null,
    signal = null,
  } = options;

  if (typeof fetchPage !== 'function') {
    throw new TypeError('fetchPage must be a function');
  }
  if (maxRetries < 0) {
    throw new RangeError('maxRetries must be non-negative');
  }
  if (baseDelay <= 0) {
    throw new RangeError('baseDelay must be positive');
  }

  const allItems = [];
  let cursor = undefined;
  let pageCount = 0;

  while (true) {
    if (signal?.aborted) {
      throw new DOMException('Aborted', 'AbortError');
    }

    const page = await _fetchWithRetry(fetchPage, cursor, {
      maxRetries,
      baseDelay,
      maxDelay,
      backoffFactor,
      onRetry,
      signal,
    });

    allItems.push(...page.items);
    pageCount++;

    if (!page.nextCursor || page.items.length === 0) {
      break;
    }
    cursor = page.nextCursor;
  }

  return { items: allItems, pages: pageCount };
}

/**
 * Internal: fetches a single page with retry + exponential backoff.
 */
async function _fetchWithRetry(fetchPage, cursor, opts) {
  let lastError;

  for (let attempt = 0; attempt <= opts.maxRetries; attempt++) {
    if (opts.signal?.aborted) {
      throw new DOMException('Aborted', 'AbortError');
    }

    try {
      return await fetchPage(cursor);
    } catch (err) {
      lastError = err;

      if (attempt === opts.maxRetries) {
        break;
      }

      const delay = Math.min(
        opts.baseDelay * Math.pow(opts.backoffFactor, attempt),
        opts.maxDelay,
      );

      if (opts.onRetry) {
        opts.onRetry(err, attempt + 1, delay);
      }

      await _sleep(delay, opts.signal);
    }
  }

  throw new Error(
    `Failed after ${opts.maxRetries + 1} attempts: ${lastError.message}`,
    { cause: lastError },
  );
}

function _sleep(ms, signal) {
  return new Promise((resolve, reject) => {
    if (signal?.aborted) {
      reject(new DOMException('Aborted', 'AbortError'));
      return;
    }

    const timer = setTimeout(resolve, ms);

    signal?.addEventListener(
      'abort',
      () => {
        clearTimeout(timer);
        reject(new DOMException('Aborted', 'AbortError'));
      },
      { once: true },
    );
  });
}

module.exports = { retry_with_backoff, _fetchWithRetry, _sleep };

const { retry_with_backoff, _fetchWithRetry, _sleep } = require('./retry_with_backoff');

// ── helpers ──────────────────────────────────────────────────────────────────

/** Builds a fetchPage function backed by a page array. */
function mockFetchPage(pages) {
  // pages: [{ items, nextCursor?, failTimes? }, ...]
  let callIndex = 0;
  let attemptsOnCurrentPage = 0;

  return async (cursor) => {
    const page = pages[callIndex];
    if (!page) throw new Error('mockFetchPage: no more pages');

    attemptsOnCurrentPage++;
    if (page.failTimes && attemptsOnCurrentPage <= page.failTimes) {
      throw new Error(`simulated failure ${attemptsOnCurrentPage}`);
    }

    callIndex++;
    attemptsOnCurrentPage = 0;
    return { items: page.items, nextCursor: page.nextCursor };
  };
}

// ── test runner (minimal) ────────────────────────────────────────────────────

const tests = [];
let passed = 0;
let failed = 0;

function test(name, fn) {
  tests.push({ name, fn });
}

async function run() {
  for (const t of tests) {
    try {
      await t.fn();
      passed++;
      console.log(`  PASS  ${t.name}`);
    } catch (err) {
      failed++;
      console.log(`  FAIL  ${t.name}`);
      console.log(`        ${err.message}`);
    }
  }
  console.log(`\n${passed} passed, ${failed} failed, ${tests.length} total`);
  process.exit(failed > 0 ? 1 : 0);
}

// ── tests ────────────────────────────────────────────────────────────────────

// Happy-path pagination

test('single page, no cursor', async () => {
  const fetchPage = mockFetchPage([{ items: [1, 2, 3] }]);
  const result = await retry_with_backoff(fetchPage, { baseDelay: 10 });
  expect(result.items).toEqual([1, 2, 3]);
  expect(result.pages).toBe(1);
});

test('multiple pages', async () => {
  const fetchPage = mockFetchPage([
    { items: [1], nextCursor: 'a' },
    { items: [2], nextCursor: 'b' },
    { items: [3] },
  ]);
  const result = await retry_with_backoff(fetchPage, { baseDelay: 10 });
  expect(result.items).toEqual([1, 2, 3]);
  expect(result.pages).toBe(3);
});

test('empty first page terminates immediately', async () => {
  const fetchPage = mockFetchPage([{ items: [] }]);
  const result = await retry_with_backoff(fetchPage, { baseDelay: 10 });
  expect(result.items).toEqual([]);
  expect(result.pages).toBe(1);
});

test('page with empty nextCursor terminates', async () => {
  const fetchPage = mockFetchPage([
    { items: ['a'], nextCursor: '' },
    // second call should not happen
  ]);
  const result = await retry_with_backoff(fetchPage, { baseDelay: 10 });
  expect(result.items).toEqual(['a']);
  expect(result.pages).toBe(1);
});

test('many pages accumulate correctly', async () => {
  const pages = Array.from({ length: 50 }, (_, i) => ({
    items: [i],
    nextCursor: i < 49 ? String(i + 1) : undefined,
  }));
  const fetchPage = mockFetchPage(pages);
  const result = await retry_with_backoff(fetchPage, { baseDelay: 10 });
  expect(result.items).toEqual(Array.from({ length: 50 }, (_, i) => i));
  expect(result.pages).toBe(50);
});

// Retry / backoff

test('retries on transient failure then succeeds', async () => {
  let attempts = 0;
  const fetchPage = async (cursor) => {
    attempts++;
    if (attempts === 1) throw new Error('timeout');
    return { items: [42] };
  };
  const result = await retry_with_backoff(fetchPage, {
    baseDelay: 10,
    maxRetries: 3,
  });
  expect(result.items).toEqual([42]);
  expect(attempts).toBe(2);
});

test('retries multiple times before succeeding', async () => {
  let attempts = 0;
  const fetchPage = async () => {
    attempts++;
    if (attempts <= 3) throw new Error(`fail ${attempts}`);
    return { items: ['ok'] };
  };
  const result = await retry_with_backoff(fetchPage, {
    baseDelay: 10,
    maxRetries: 5,
  });
  expect(result.items).toEqual(['ok']);
  expect(attempts).toBe(4);
});

test('throws after exceeding maxRetries', async () => {
  const fetchPage = async () => {
    throw new Error('always fails');
  };
  await expectThrows(
    () => retry_with_backoff(fetchPage, { baseDelay: 10, maxRetries: 2 }),
    'Failed after 3 attempts: always fails',
  );
});

test('retries on second page failure', async () => {
  let page2Attempts = 0;
  const fetchPage = (() => {
    let call = 0;
    return async () => {
      call++;
      if (call === 1) return { items: [1], nextCursor: 'x' };
      page2Attempts++;
      if (page2Attempts <= 1) throw new Error('page2 fail');
      return { items: [2] };
    };
  })();
  const result = await retry_with_backoff(fetchPage, {
    baseDelay: 10,
    maxRetries: 3,
  });
  expect(result.items).toEqual([1, 2]);
  expect(page2Attempts).toBe(2);
});

test('backoff factor increases delay', async () => {
  const delays = [];
  const fetchPage = async () => {
    throw new Error('fail');
  };
  try {
    await retry_with_backoff(fetchPage, {
      baseDelay: 100,
      backoffFactor: 3,
      maxRetries: 3,
      maxDelay: 10000,
      onRetry: (_err, _attempt, delay) => delays.push(delay),
    });
  } catch {
    // expected
  }
  expect(delays).toEqual([100, 300, 900]);
});

test('delay is capped at maxDelay', async () => {
  const delays = [];
  const fetchPage = async () => { throw new Error('fail'); };
  try {
    await retry_with_backoff(fetchPage, {
      baseDelay: 1000,
      backoffFactor: 10,
      maxRetries: 4,
      maxDelay: 3000,
      onRetry: (_err, _a, delay) => delays.push(delay),
    });
  } catch {
    // expected
  }
  expect(delays).toEqual([1000, 3000, 3000, 3000]);
});

test('onRetry callback is invoked with correct args', async () => {
  const calls = [];
  const fetchPage = async () => { throw new Error('boom'); };
  try {
    await retry_with_backoff(fetchPage, {
      baseDelay: 10,
      maxRetries: 2,
      onRetry: (err, attempt, delay) =>
        calls.push({ message: err.message, attempt, delay }),
    });
  } catch {
    // expected
  }
  expect(calls.length).toBe(2);
  expect(calls[0]).toEqual({ message: 'boom', attempt: 1, delay: 10 });
  expect(calls[1]).toEqual({ message: 'boom', attempt: 2, delay: 20 });
});

test('maxRetries=0 means no retries (one attempt only)', async () => {
  let attempts = 0;
  const fetchPage = async () => {
    attempts++;
    throw new Error('fail');
  };
  await expectThrows(
    () => retry_with_backoff(fetchPage, { baseDelay: 10, maxRetries: 0 }),
    'Failed after 1 attempts: fail',
  );
  expect(attempts).toBe(1);
});

// AbortSignal

test('aborts before first request', async () => {
  const controller = new AbortController();
  controller.abort();
  const fetchPage = async () => { throw new Error('should not reach'); };
  await expectThrows(
    () =>
      retry_with_backoff(fetchPage, {
        baseDelay: 10,
        signal: controller.signal,
      }),
    'Aborted',
  );
});

test('aborts during backoff sleep', async () => {
  const controller = new AbortController();
  let fetchCalls = 0;
  const fetchPage = async () => {
    fetchCalls++;
    throw new Error('fail');
  };
  // abort after a short delay
  setTimeout(() => controller.abort(), 50);
  await expectThrows(
    () =>
      retry_with_backoff(fetchPage, {
        baseDelay: 5000,
        maxRetries: 5,
        signal: controller.signal,
      }),
    'Aborted',
  );
  expect(fetchCalls).toBe(1);
});

test('aborts between pages', async () => {
  const controller = new AbortController();
  const fetchPage = (() => {
    let call = 0;
    return async () => {
      call++;
      if (call === 1) return { items: [1], nextCursor: 'x' };
      throw new Error('should not reach second page');
    };
  })();
  // abort before second page fetch
  setTimeout(() => controller.abort(), 50);
  await expectThrows(
    () =>
      retry_with_backoff(fetchPage, {
        baseDelay: 10,
        signal: controller.signal,
      }),
    'Aborted',
  );
});

// Validation

test('throws TypeError if fetchPage is not a function', async () => {
  await expectThrows(
    () => retry_with_backoff('not a function'),
    'fetchPage must be a function',
  );
});

test('throws RangeError for negative maxRetries', async () => {
  await expectThrows(
    () => retry_with_backoff(async () => ({}), { maxRetries: -1 }),
    'maxRetries must be non-negative',
  );
});

test('throws RangeError for non-positive baseDelay', async () => {
  await expectThrows(
    () => retry_with_backoff(async () => ({}), { baseDelay: 0 }),
    'baseDelay must be positive',
  );
});

test('throws RangeError for negative baseDelay', async () => {
  await expectThrows(
    () => retry_with_backoff(async () => ({}), { baseDelay: -100 }),
    'baseDelay must be positive',
  );
});

// Preserves original error as cause

test('original error is preserved as cause', async () => {
  const original = new Error('network timeout');
  const fetchPage = async () => { throw original; };
  try {
    await retry_with_backoff(fetchPage, { baseDelay: 10, maxRetries: 1 });
    throw new Error('should have thrown');
  } catch (err) {
    expect(err.message).toBe('Failed after 2 attempts: network timeout');
    expect(err.cause).toBe(original);
  }
});

// Mixed item types

test('handles various item types', async () => {
  const fetchPage = mockFetchPage([
    { items: [1, 'two', { three: 3 }, null], nextCursor: 'a' },
    { items: [[4, 5], true], nextCursor: '' },
  ]);
  const result = await retry_with_backoff(fetchPage, { baseDelay: 10 });
  expect(result.items).toEqual([1, 'two', { three: 3 }, null, [4, 5], true]);
  expect(result.pages).toBe(2);
});

// Retry per page is independent

test('exhausted retries on one page does not affect next page', async () => {
  const pages = [
    { items: [1], nextCursor: 'a', failTimes: 2 },
    { items: [2] },
  ];
  const fetchPage = mockFetchPage(pages);
  const result = await retry_with_backoff(fetchPage, {
    baseDelay: 10,
    maxRetries: 3,
  });
  expect(result.items).toEqual([1, 2]);
});

// ── _sleep tests ─────────────────────────────────────────────────────────────

test('_sleep resolves after specified duration', async () => {
  const start = Date.now();
  await _sleep(50);
  const elapsed = Date.now() - start;
  expect(elapsed >= 40).toBe(true); // allow small timing variance
});

test('_sleep rejects immediately if signal already aborted', async () => {
  const controller = new AbortController();
  controller.abort();
  await expectThrows(() => _sleep(1000, controller.signal), 'Aborted');
});

// ── assertion helpers ────────────────────────────────────────────────────────

function expect(actual) {
  return {
    toEqual(expected) {
      const a = JSON.stringify(actual);
      const e = JSON.stringify(expected);
      if (a !== e) {
        throw new Error(`Expected ${e}, got ${a}`);
      }
    },
    toBe(expected) {
      if (actual !== expected) {
        throw new Error(`Expected ${expected}, got ${actual}`);
      }
    },
  };
}

async function expectThrows(fn, message) {
  try {
    await fn();
    throw new Error(`Expected error "${message}" but no error was thrown`);
  } catch (err) {
    if (!err.message.includes(message)) {
      throw new Error(
        `Expected error message to include "${message}", got "${err.message}"`,
      );
    }
  }
}

// ── run ──────────────────────────────────────────────────────────────────────

run();
